"""Real WebGL, Rapier, touch, review, UI bindings and persistence checks."""
import os,subprocess,time
from playwright.sync_api import sync_playwright,expect
server=subprocess.Popen(['node','scripts/serve.mjs'],env={**os.environ,'PORT':'14337'},stdout=subprocess.DEVNULL)
BASE='http://127.0.0.1:14337'
try:
 with sync_playwright() as p:
  browser=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader'])
  errors=[]
  def load(context,template):
   page=context.new_page();page.on('pageerror',lambda e:errors.append(str(e)));page.goto(BASE);page.evaluate('''async t=>{const{createProject}=await import('/project.js');const p=createProject('QA game',t);p.objects=p.objects.filter(o=>o.mesh!=='hazard');const coin=p.objects.find(o=>o.mesh==='coin');if(coin){coin.x=0;coin.z=-4;coin.y=1;}localStorage.setItem('playform.projects',JSON.stringify([p]))}''',template);page.reload();page.locator('.project-open').click();return page
  desktop=browser.new_context(viewport={'width':1440,'height':960});page=load(desktop,'runner3d');expect(page.locator('#three-play')).to_be_visible();page.wait_for_timeout(700)
  # Add and customize a button, save, reload and verify persistence.
  page.locator('[data-action="ui"]').click();page.locator('#ui-jump').click();page.locator('[data-field="text"]').fill('Jump now');page.locator('[data-field="text"]').dispatch_event('change');page.locator('#ui-save').click();page.reload();page.locator('.project-open').click();expect(page.locator('#three-play')).to_be_visible();page.locator('#three-play').click();page.wait_for_timeout(650);expect(page.locator('.studio3d')).to_have_attribute('data-grounded','true');z=float(page.locator('.studio3d').get_attribute('data-z'));assert z<0;expect(page.locator('.three-runtime')).to_contain_text('Coins 1')
  page.get_by_role('button',name='Jump now',exact=True).click();page.wait_for_timeout(100);assert float(page.locator('.studio3d').get_attribute('data-y'))>1.1
  page.wait_for_timeout(900);page.keyboard.press('ArrowLeft');expect(page.locator('.studio3d')).to_have_attribute('data-lane','0');page.keyboard.press('ArrowRight');expect(page.locator('.studio3d')).to_have_attribute('data-lane','1');page.keyboard.press('ArrowDown');expect(page.locator('.studio3d')).to_have_attribute('data-animation','slide');page.wait_for_timeout(1000);assert page.locator('.studio3d').get_attribute('data-animation')!='slide';assert float(page.locator('.studio3d').get_attribute('data-z'))<z-10
  page.screenshot(path='screenshots/3d-runner-tested.png');print('PASS 3D physics, UI jump, continuous run, keyboard lanes, slide/stand',flush=True)
  page.locator('#three-play').click();page.locator('#three-camera').select_option('top');page.locator('[data-add="box"]').click();page.locator('[data-field="x"]').fill('3');page.locator('[data-field="x"]').dispatch_event('change');page.locator('[data-action="undo"]').click();page.locator('[data-action="redo"]').click();page.screenshot(path='screenshots/3d-editor-tested.png');print('PASS 3D camera, object creation, transforms, undo/redo',flush=True);page.close()
  phone=browser.new_context(viewport={'width':390,'height':844},is_mobile=True,has_touch=True,device_scale_factor=1);mobile=load(phone,'runner3d');expect(mobile.locator('#three-play')).to_be_visible();mobile.locator('#three-play').click();mobile.wait_for_timeout(650)
  cdp=phone.new_cdp_session(mobile)
  def swipe(direction):
   r=mobile.locator('canvas').bounding_box();x=r['x']+r['width']/2;y=r['y']+r['height']*.58;dx,dy={'up':(0,-110),'down':(0,110),'left':(-95,0),'right':(95,0)}[direction]
   cdp.send('Input.dispatchTouchEvent',{'type':'touchStart','touchPoints':[{'x':x,'y':y}]})
   cdp.send('Input.dispatchTouchEvent',{'type':'touchMove','touchPoints':[{'x':x+dx,'y':y+dy}]})
   cdp.send('Input.dispatchTouchEvent',{'type':'touchEnd','touchPoints':[]})
  swipe('left');expect(mobile.locator('.studio3d')).to_have_attribute('data-lane','0');swipe('right');expect(mobile.locator('.studio3d')).to_have_attribute('data-lane','1');swipe('up');mobile.wait_for_timeout(100);assert float(mobile.locator('.studio3d').get_attribute('data-y'))>1.1;mobile.wait_for_timeout(900);swipe('down');expect(mobile.locator('.studio3d')).to_have_attribute('data-animation','slide');mobile.screenshot(path='screenshots/3d-phone-tested.png');assert mobile.evaluate('document.documentElement.scrollWidth<=innerWidth');print('PASS actual phone touch swipes in all four directions',flush=True)
  mobile.locator('#three-play').click();mobile.locator('.three-nav [data-tab="Inspector"]').click();expect(mobile.locator('.three-inspector')).to_be_visible();mobile.locator('.three-nav [data-tab="Events"]').click();expect(mobile.locator('.three-events')).to_be_visible();print('PASS mobile collapsible panels',flush=True);mobile.close()
  # Rapier sensor contacts and a solid wall must affect real gameplay.
  physics=desktop.new_page();physics.goto(BASE);physics.evaluate("""async()=>{const{createProject}=await import('/project.js');const{make3DObject}=await import('/project-3d.js');const p=createProject('Physics','runner3d');p.objects=p.objects.filter(o=>['character','ground'].includes(o.mesh));const hazard=make3DObject('hazard',0,1.5,-7);hazard.h=.6;hazard.w=2;p.objects.push(hazard);const wall=make3DObject('box',0,1.5,-13);wall.h=3;wall.w=6;p.objects.push(wall);localStorage.setItem('playform.projects',JSON.stringify([p]))}""");physics.reload();physics.locator('.project-open').click();physics.locator('#three-play').click();physics.wait_for_timeout(1200);expect(physics.locator('.three-runtime')).to_contain_text('Health 2');physics.wait_for_timeout(850);assert float(physics.locator('.studio3d').get_attribute('data-z'))>-13;physics.locator('[data-action="restart"]').click();physics.wait_for_timeout(400);physics.keyboard.press('ArrowDown');physics.wait_for_timeout(650);expect(physics.locator('.three-runtime')).to_contain_text('Health 3');physics.screenshot(path='screenshots/3d-slide-clearance.png');physics.close();print('PASS hazard contact, solid collision, slide clearance',flush=True)
  # Mount the real setup to exercise proposal approval and skip independently.
  review=desktop.new_page();review.goto(BASE);review.evaluate('''async()=>{const{createProject}=await import('/project.js');const{mountSetup}=await import('/setup.js');const p=createProject('Review','blank3d');p.description='A mobile lane runner, jump and collect coins';p.ui=[];window.qaProject=p;window.qaDone=false;mountSetup({root:document.querySelector('#app'),project:p,onComplete:()=>window.qaDone=true,onCancel:()=>{},notify:()=>{}})}''');review.locator('#skip-assets').click();review.locator('#enter-studio').click();expect(review.get_by_role('heading',name='Suggested game setup')).to_be_visible();assert review.evaluate('qaProject.runner===undefined && qaProject.ui.length===0');review.get_by_role('button',name='Apply selected & open studio').click();assert review.evaluate('qaDone && qaProject.runner.enabled && qaProject.ui.some(e=>e.action==="jump") && qaProject.variables.JumpHeight===8');print('PASS description setup requires explicit confirmation',flush=True)
  two=load(desktop,'platformer');two.locator('.desktop-menus [data-action="game-ui"]').evaluate('(e)=>e.click()');two.locator('#ui-jump').click();two.locator('#ui-coins').click();two.locator('#ui-save').click();two.locator('.editor-commandbar [data-action="play"]').first.click();two.wait_for_timeout(700);two.get_by_role('button',name='Jump',exact=True).click();two.wait_for_timeout(120);assert two.locator('.game-ui-layer').is_visible();expect(two.locator('.game-ui-layer')).to_contain_text('Coins 0');two.screenshot(path='screenshots/2d-ui-tested.png');print('PASS same UI builder and live bindings in 2D',flush=True)
  assert not errors,errors
  browser.close()
finally:server.terminate();server.wait()
